package com.fde.ho2.agent; import com.fde.ho2.model.*; import java.util.Map; public class ResponseAgent implements Agent { public AgentType type(){return AgentType.RESPONSE;} public AgentResult execute(String id,Map<AgentType,AgentResult> d){String a=d.getOrDefault(AgentType.ORDER_ANALYSIS,new AgentResult(type(),"ORDER ANALYSIS MISSING")).output(); String i=d.getOrDefault(AgentType.INVENTORY,new AgentResult(type(),"INVENTORY MISSING")).output(); return new AgentResult(type(),a+" "+i);}}
